INSERT dbo.TK_RuntimeAreaControl (AreaKey, DesiredEnabled, ActualState, LastCommandAt, LastAppliedAt, LastStartAt, LastStopAt, LastError, CreatedAt, UpdatedAt)
SELECT AreaKey, 0, N'Stopped', NULL, NULL, NULL, NULL, NULL, SYSDATETIME(), SYSDATETIME()
FROM (VALUES (N'SIPInt'), (N'Provider'), (N'GSM'), (N'SVC')) AS Areas(AreaKey);

-- Generische lokale Benutzer ohne persoenliche Namen, E-Mail oder ADS-Bezug.
INSERT dbo.TK_SIP_User
    (Username, Telefonnummer, [Password], DisplayName, [Description], UserType,
     Active, CanDialInternal, CanDialExternal, CanReceiveInternal, CanReceiveExternal,
     SortOrder, CreatedAt)
SELECT Benutzername, Nummer, VerschluesseltesPasswort, N'Benutzer ' + Nummer, N'Lokaler Installationsbenutzer', N'SIPUser',
       1, 1, 1, 1, 1, Sortierung, SYSDATETIME()
FROM (VALUES (N'1001', N'user1', N'F8N47adaeXGcm93VWIGkPg==', 10), (N'1002', N'user2', N'AUR247IsmBjlAfYMMaGloA==', 20), (N'1003', N'user3', N'dfBEtIq5wyOxOV8JHOTknQ==', 30),
             (N'1004', N'user4', N'NxWrIgKVZISyPzBlGsx6MQ==', 40), (N'1005', N'user5', N'+7v0y6gCbmOTAMMzkVIYWQ==', 50))
     AS Benutzer(Nummer, Benutzername, VerschluesseltesPasswort, Sortierung);

-- Vorbelegte Nummern ohne Providerbindung; erst nach Anschlusskonfiguration aktivieren.
INSERT dbo.TK_Notruf
    (Notrufnummer, Bezeichnung, TargetType, TargetValue, ProviderAccountID, Priority, Active, CreatedAt)
VALUES
    (N'110', N'Polizei', N'External', N'110', NULL, 1, 0, SYSDATETIME()),
    (N'112', N'Feuerwehr / Rettungsdienst', N'External', N'112', NULL, 1, 0, SYSDATETIME()),
    (N'116117', N'Aerztlicher Bereitschaftsdienst', N'External', N'116117', NULL, 1, 0, SYSDATETIME());

-- Abschlusspruefung innerhalb der Installationstransaktion.
IF (SELECT COUNT(*) FROM dbo.TK_SIP_User WHERE Active = 1 AND UserType = N'SIPUser') <> 5
    THROW 51002, N'Es muessen genau fuenf aktive lokale SIP-Benutzer vorhanden sein.', 1;
IF EXISTS (SELECT 1 FROM dbo.TK_SIP_User WHERE [Password] = Username OR NULLIF([Password], N'') IS NULL)
    THROW 51003, N'Installationspasswoerter muessen mit sipcryptlib verschluesselt gespeichert sein.', 1;
IF EXISTS (SELECT 1 FROM dbo.TK_ProviderAccounts)
    THROW 51004, N'Providerkonten muessen bei der Erstinstallation leer sein.', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.TK_SIP_ServiceLeg WHERE ServiceCode = N'MAIN_MENU' AND InternalNumber = N'*100' AND Active = 1)
    THROW 51005, N'Service-Hauptmenue fehlt.', 1;
IF (SELECT COUNT(*) FROM dbo.TK_RuntimeAreaControl WHERE DesiredEnabled = 0 AND ActualState = N'Stopped') <> 4
    THROW 51006, N'Runtime-Bereiche nicht korrekt initialisiert.', 1;
COMMIT TRANSACTION;
PRINT N'TK-Server-Datenbank mit Standardwerten erstellt. Bereiche sind gestoppt.';
GO
